    "glossary": [
      {
        "term": "Inheritance",
        "definition": "A mechanism wherein a new subclass derives properties and behaviors from an existing superclass using the extends keyword."
      },
      {
        "term": "Polymorphism",
        "definition": "The ability of an object reference of a supertype to refer to objects of different subtypes and execute their overridden behaviors dynamically."
      },
      {
        "term": "Dynamic Method Dispatch",
        "definition": "The runtime mechanism by which the JVM resolves a call to an overridden method based on the actual object instance on the heap."
      },
      {
        "term": "Virtual Method Table (vtable)",
        "definition": "An internal JVM data structure storing function pointers for dynamic method resolution."
      },
      {
        "term": "Abstract Class",
        "definition": "A class declared with the abstract keyword that cannot be instantiated and may contain abstract methods requiring subclass implementation."
      },
      {
        "term": "Interface",
        "definition": "A reference type specifying a contract of methods that implementing classes must satisfy."
      },
      {
        "term": "Default Method",
        "definition": "A method inside an interface declared with the default keyword that provides a concrete default implementation."
      },
      {
        "term": "Classes Win Rule",
        "definition": "The Java conflict resolution rule stating that superclass implementations always override interface default methods."
      }
    ],
