    "glossary": [
      {
        "term": "Generics",
        "definition": "A language facility enabling classes, interfaces, and methods to operate on parameterized types with compile-time type safety."
      },
      {
        "term": "Type Erasure",
        "definition": "The translation process where the Java compiler removes generic type arguments and inserts appropriate casts into bytecode."
      },
      {
        "term": "Bounded Type Parameter",
        "definition": "A type parameter restricted to subtypes of specified bounds using the extends keyword."
      },
      {
        "term": "PECS Principle",
        "definition": "Producer Extends, Consumer Super: use ? extends T when reading data and ? super T when writing data."
      },
      {
        "term": "HashSet",
        "definition": "An unordered Set implementation backed by a hash table providing O(1) performance for basic operations."
      },
      {
        "term": "TreeSet",
        "definition": "A NavigableSet implementation backed by a Red-Black tree that maintains elements in sorted order."
      },
      {
        "term": "Deque",
        "definition": "A double-ended queue supporting element insertion and removal at both endpoints."
      },
      {
        "term": "Comparable",
        "definition": "An interface defining the natural ordering of objects of a class via the compareTo method."
      },
      {
        "term": "Comparator",
        "definition": "A functional interface defining an external strategy for comparing pairs of objects."
      }
    ],
