    "glossary": [
      {
        "term": "Thread",
        "definition": "An independent sequence of execution within a process that shares heap memory with other threads while maintaining a private stack."
      },
      {
        "term": "Race Condition",
        "definition": "A flaw where system behavior is dependent on the uncontrolled sequence or timing of concurrent threads."
      },
      {
        "term": "Intrinsic Lock (Monitor)",
        "definition": "A built-in mutual exclusion lock present in every Java object, acquired via the synchronized keyword."
      },
      {
        "term": "volatile",
        "definition": "A Java keyword ensuring cross-thread memory visibility and preventing compiler/CPU instruction reordering."
      },
      {
        "term": "ExecutorService",
        "definition": "A JDK framework that manages a pool of worker threads and an internal task queue to execute asynchronous jobs."
      },
      {
        "term": "Future",
        "definition": "An object representing the pending result of an asynchronous computation."
      },
      {
        "term": "Compare-And-Swap (CAS)",
        "definition": "An atomic CPU hardware instruction used by atomic variables to update memory only if it matches an expected value."
      },
      {
        "term": "CountDownLatch",
        "definition": "A synchronization primitive that causes threads to wait until a countdown reaches zero."
      },
      {
        "term": "BlockingQueue",
        "definition": "A thread-safe FIFO queue that blocks when attempting to dequeue from an empty queue or enqueue to a full queue."
      },
      {
        "term": "Deadlock",
        "definition": "A situation where two or more threads are permanently blocked, each waiting for a lock held by the other."
      }
    ],
